CREATE TABLE settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE login_tokens(id TEXT PRIMARY KEY,hash TEXT NOT NULL UNIQUE,label TEXT NOT NULL,created_at TEXT NOT NULL,last_used_at TEXT NOT NULL,revoked_at TEXT);
CREATE TABLE sessions(hash TEXT PRIMARY KEY,expires TEXT NOT NULL,token_id TEXT REFERENCES login_tokens(id));
CREATE TABLE oauth_codes(hash TEXT PRIMARY KEY,data TEXT NOT NULL,expires TEXT NOT NULL);
CREATE TABLE worker_registrations(id TEXT PRIMARY KEY,worker_id TEXT,principal TEXT,artifact_id TEXT,body TEXT,state TEXT);
CREATE TABLE oauth_clients(id TEXT PRIMARY KEY,name TEXT NOT NULL,redirects TEXT NOT NULL,secret_hash TEXT,method TEXT NOT NULL,created_at TEXT NOT NULL,revoked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE oauth_tokens(hash TEXT PRIMARY KEY,refresh_hash TEXT UNIQUE,client_id TEXT NOT NULL REFERENCES oauth_clients(id),scopes TEXT NOT NULL,expires TEXT NOT NULL,refresh_expires TEXT NOT NULL,resource TEXT NOT NULL,revoked INTEGER NOT NULL DEFAULT 0,operator_name TEXT);
CREATE TABLE tower_enrollments(id TEXT PRIMARY KEY,credential_id TEXT,state TEXT);
CREATE TABLE task_comments(id TEXT PRIMARY KEY);
CREATE TABLE IF NOT EXISTS tasks(id TEXT PRIMARY KEY,project_id TEXT,status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','done','cancelled')),closed_at TEXT,created_at TEXT,updated_at TEXT);
CREATE INDEX tasks_v5_project ON tasks(project_id,status,updated_at);
CREATE TABLE task_blockers(id TEXT PRIMARY KEY,task_id TEXT REFERENCES tasks(id),waiting_on TEXT,body TEXT,created_at TEXT,resolved_at TEXT);
CREATE TABLE task_prerequisites(task_id TEXT REFERENCES tasks(id),prerequisite_id TEXT REFERENCES tasks(id));
CREATE TABLE task_claims(task_id TEXT PRIMARY KEY REFERENCES tasks(id));
CREATE TABLE entities(id TEXT PRIMARY KEY,kind TEXT,project_id TEXT);
CREATE TABLE artifacts(id TEXT PRIMARY KEY,title TEXT);
CREATE TABLE threads(id TEXT PRIMARY KEY);
CREATE TABLE comments(id TEXT PRIMARY KEY,thread_id TEXT);
CREATE TABLE artifact_comments(id TEXT PRIMARY KEY);
CREATE TABLE artifact_versions(artifact_id TEXT,seq INTEGER);
CREATE TRIGGER artifact_context_cleanup BEFORE DELETE ON artifacts BEGIN SELECT 1; END;
CREATE TRIGGER artifact_thread_context_cleanup BEFORE DELETE ON threads BEGIN SELECT 1; END;
CREATE TABLE session_events(id TEXT PRIMARY KEY,source_id TEXT,payload TEXT NOT NULL);
CREATE TABLE session_assets(id TEXT PRIMARY KEY,created_at TEXT);
CREATE TRIGGER session_events_immutable BEFORE UPDATE ON session_events BEGIN SELECT RAISE(ABORT,'Session events are append-only'); END;
CREATE TABLE artifact_entities(entity_id TEXT PRIMARY KEY,artifact_id TEXT);
